import React from "react";
import "./../css/index.css";
import { FaRegBell } from "react-icons/fa";

import withRouter from "./withRouter";
import AuthCheck from "./AuthCheckComponent";
import Loader from "./LoaderComponent";

const API_URL = "https://iranaserviceapp.ir/test/api";

class Home extends React.Component {
  constructor(props) {
    super(props);

    this.state = {
      authChecking: true,
      authenticated: false,

      loading: true,

      popularCities: [],
      activeRepairmen: [],

      cityLimit: 3,
      cityPeriod: "week",

      repairmanLimit: 3,
      repairmanPeriod: "week",
    };
  }

  componentDidMount() {
    const isAuthenticated = AuthCheck();

    if (!isAuthenticated) {
      return;
    }

    this.setState(
      {
        authChecking: false,
        authenticated: true,
      },
      () => {
        this.getHome();
      }
    );
  }

  getHome = () => {
    const token = localStorage.getItem("token");

    this.setState({
      loading: true,
    });

    fetch(`${API_URL}/home`, {
      method: "GET",

      headers: {
        Accept: "application/json",
        Authorization: `Bearer ${token}`,
      },
    })
      .then(async (response) => {
        const data = await response.json();

        console.log("HOME RESPONSE:", data);

        if (!response.ok) {
          throw new Error(
            data.message || "خطا در دریافت اطلاعات صفحه اصلی"
          );
        }

        return data;
      })
      .then((data) => {
        /*
         * اطلاعات شهرها
         *
         * بسته به ساختار API ممکن است نام کلید
         * popularCities / cities / city باشد.
         */

        const cities =
          data.popularCities ||
          data.popular_cities ||
          data.cities ||
          data.city ||
          [];

        /*
         * اطلاعات تعمیرکاران
         */

        const repairmen =
          data.activeRepairmen ||
          data.active_repairmen ||
          data.repairmen ||
          data.users ||
          data.user ||
          [];

        this.setState({
          popularCities: Array.isArray(cities)
            ? cities
            : [],

          activeRepairmen: Array.isArray(repairmen)
            ? repairmen
            : [],

          loading: false,
        });
      })
      .catch((error) => {
        console.error("HOME ERROR:", error);

        this.setState({
          loading: false,
        });
      });
  };

  /*
   * ==============================
   * تغییر تعداد شهرها
   * ==============================
   */

  handleCityLimitChange = (e) => {
    this.setState({
      cityLimit: Number(e.target.value),
    });
  };

  /*
   * ==============================
   * تغییر بازه شهرها
   * ==============================
   */

  handleCityPeriodChange = (e) => {
    this.setState({
      cityPeriod: e.target.value,
    });
  };

  /*
   * ==============================
   * تغییر تعداد تعمیرکاران
   * ==============================
   */

  handleRepairmanLimitChange = (e) => {
    this.setState({
      repairmanLimit: Number(e.target.value),
    });
  };

  /*
   * ==============================
   * تغییر بازه تعمیرکاران
   * ==============================
   */

  handleRepairmanPeriodChange = (e) => {
    this.setState({
      repairmanPeriod: e.target.value,
    });
  };

  /*
   * ==============================
   * نام تعمیرکار
   * ==============================
   */

  getRepairmanName = (repairman) => {
    const name =
      repairman.name ||
      repairman.first_name ||
      "";

    const family =
      repairman.family ||
      repairman.last_name ||
      "";

    return `${name} ${family}`.trim() || "بدون نام";
  };

  /*
   * ==============================
   * تعداد درخواست تعمیرکار
   * ==============================
   */

  getRepairmanRequests = (repairman) => {
    const period = this.state.repairmanPeriod;

    if (period === "week") {
      return Number(repairman.reqs7 || 0);
    }

    if (period === "month") {
      return Number(repairman.reqs30 || 0);
    }

    if (period === "year") {
      return Number(repairman.reqs365 || repairman.reqs180 || 0);
    }

    return Number(repairman.reqs7 || 0);
  };

  /*
   * ==============================
   * عکس تعمیرکار
   * ==============================
   */

  getRepairmanImage = (repairman) => {
    if (!repairman.image) {
      const name = this.getRepairmanName(repairman);

      return `https://ui-avatars.com/api/?name=${encodeURIComponent(
        name
      )}&background=e9ecef&color=495057&size=40&rounded=true`;
    }

    return `https://iranaserviceapp.ir/test/${String(
      repairman.image
    ).replace(/^\/+/, "")}`;
  };

  /*
   * ==============================
   * شهر
   * ==============================
   */

  getCityName = (city) => {
    if (typeof city === "string") {
      return city;
    }

    return (
      city.name ||
      city.city_name ||
      city.title ||
      "بدون نام"
    );
  };

  /*
   * ==============================
   * تعداد درخواست شهر
   * ==============================
   */

  getCityRequests = (city) => {
    const period = this.state.cityPeriod;

    if (period === "week") {
      return Number(
        city.reqs7 ||
        city.requests7 ||
        city.count7 ||
        city.count ||
        0
      );
    }

    if (period === "month") {
      return Number(
        city.reqs30 ||
        city.requests30 ||
        city.count30 ||
        city.count ||
        0
      );
    }

    if (period === "year") {
      return Number(
        city.reqs365 ||
        city.reqs180 ||
        city.requests365 ||
        city.requests180 ||
        city.count ||
        0
      );
    }

    return 0;
  };

  render() {
    if (this.state.authChecking) {
      return <Loader />;
    }

    if (!this.state.authenticated) {
      return null;
    }

    const {
      popularCities,
      activeRepairmen,
      cityLimit,
      cityPeriod,
      repairmanLimit,
      repairmanPeriod,
      loading,
    } = this.state;

    /*
     * محدود کردن تعداد شهرها
     */

    const displayedCities = popularCities
      .slice()
      .sort(
        (a, b) =>
          this.getCityRequests(b) -
          this.getCityRequests(a)
      )
      .slice(0, cityLimit);

    /*
     * محدود کردن تعداد تعمیرکاران
     */

    const displayedRepairmen = activeRepairmen
      .slice()
      .sort(
        (a, b) =>
          this.getRepairmanRequests(b) -
          this.getRepairmanRequests(a)
      )
      .slice(0, repairmanLimit);

    return (
      <main className="container pt-5">

        {/* ==============================
            اعلان
        ============================== */}

        <div className="fixed-top-left">
          <FaRegBell
            size={24}
            color="#495057"
          />
        </div>

        {/* ==============================
            شهرهای پر درخواست
        ============================== */}

        <div className="card shadow-sm border-0 mb-4">

          <div className="card-body p-4">

            <h4 className="h6 fw-bold text-center mb-2">
              شهرهای پر درخواست
            </h4>

            <div className="d-flex justify-content-end gap-2 mb-3 row">

              {/* تعداد */}

              <select
                value={cityLimit}
                onChange={this.handleCityLimitChange}
                className="col form-select form-select-sm bg-light text-secondary border-0"
                style={{ width: "auto" }}
              >
                <option value="3">
                  نمایش ۳ شهر
                </option>

                <option value="5">
                  نمایش ۵ شهر
                </option>

                <option value="10">
                  نمایش ۱۰ شهر
                </option>
              </select>

              {/* بازه */}

              <select
                value={cityPeriod}
                onChange={this.handleCityPeriodChange}
                className="col form-select form-select-sm bg-light text-secondary border-0"
                style={{ width: "auto" }}
              >
                <option value="week">
                  یک هفته گذشته
                </option>

                <option value="month">
                  یک ماه گذشته
                </option>

                <option value="year">
                  یک سال گذشته
                </option>
              </select>

            </div>

            <div className="scrollable-table">

              {loading ? (
                <div className="text-center text-muted py-4">
                  در حال دریافت اطلاعات...
                </div>
              ) : displayedCities.length === 0 ? (
                <div className="text-center text-muted py-4">
                  اطلاعاتی برای نمایش وجود ندارد.
                </div>
              ) : (
                <table className="table table-borderless mb-0">

                  <tbody>

                    {displayedCities.map(
                      (city, index) => (
                        <tr key={city.id || index}>

                          <td className="number-circle">
                            {index + 1}
                          </td>

                          <td>
                            {this.getCityName(city)}
                          </td>

                        </tr>
                      )
                    )}

                  </tbody>

                </table>
              )}

            </div>

          </div>

        </div>

        {/* ==============================
            فعال ترین تعمیرکاران
        ============================== */}

        <div className="card shadow-sm border-0">

          <div className="card-body p-4">

            <h4 className="h6 fw-bold text-center mb-2">
              فعال ترین تعمیرکاران
            </h4>

            <div className="d-flex justify-content-end gap-2 mb-3 row">

              {/* تعداد */}

              <select
                value={repairmanLimit}
                onChange={
                  this.handleRepairmanLimitChange
                }
                className="col form-select form-select-sm bg-light text-secondary border-0"
                style={{ width: "auto" }}
              >
                <option value="3">
                  نمایش ۳ نفر
                </option>

                <option value="5">
                  نمایش ۵ نفر
                </option>

                <option value="10">
                  نمایش ۱۰ نفر
                </option>
              </select>

              {/* بازه */}

              <select
                value={repairmanPeriod}
                onChange={
                  this.handleRepairmanPeriodChange
                }
                className="col form-select form-select-sm bg-light text-secondary border-0"
                style={{ width: "auto" }}
              >
                <option value="week">
                  یک هفته گذشته
                </option>

                <option value="month">
                  یک ماه گذشته
                </option>

                <option value="year">
                  یک سال گذشته
                </option>
              </select>

            </div>

            <div className="scrollable-list">

              {loading ? (
                <div className="text-center text-muted py-4">
                  در حال دریافت اطلاعات...
                </div>
              ) : displayedRepairmen.length ===
                0 ? (
                <div className="text-center text-muted py-4">
                  اطلاعاتی برای نمایش وجود ندارد.
                </div>
              ) : (
                <div className="d-flex flex-column gap-2">

                  {displayedRepairmen.map(
                    (repairman, index) => {

                      const requestCount =
                        this.getRepairmanRequests(
                          repairman
                        );

                      const name =
                        this.getRepairmanName(
                          repairman
                        );

                      return (
                        <div
                          key={
                            repairman.id || index
                          }
                          className="d-flex align-items-center gap-3 p-3 bg-light rounded-3"
                        >

                          <img
                            src={this.getRepairmanImage(
                              repairman
                            )}
                            alt={name}
                            className="rounded-circle"
                            width="40"
                            height="40"
                            style={{
                              objectFit: "cover",
                            }}
                          />

                          <div>

                            <div className="fw-semibold">
                              {name}
                            </div>

                            <div className="text-muted small">
                              {requestCount}{" "}
                              درخواست انجام شده
                            </div>

                          </div>

                        </div>
                      );
                    }
                  )}

                </div>
              )}

            </div>

          </div>

        </div>

      </main>
    );
  }
}

export default withRouter(Home);
